// LeetCode 347 — the k most frequent values, most frequent first; ties go to the smaller value.
public static class TopKFrequent {
    public static int[] Find(int[] nums, int k) {
        var count = new Dictionary<int, int>();
        foreach (int x in nums) count[x] = count.TryGetValue(x, out int c) ? c + 1 : 1;
        if (k < 0 || k > count.Count) throw new ArgumentOutOfRangeException(nameof(k));

        // Bucket sort by frequency: a frequency is between 1 and n, so no comparison sort over all values.
        var buckets = new List<int>[nums.Length + 1];
        foreach (var pair in count) {
            if (buckets[pair.Value] == null) buckets[pair.Value] = new List<int>();
            buckets[pair.Value].Add(pair.Key);
        }
        var result = new List<int>(k);
        for (int f = nums.Length; f >= 1 && result.Count < k; f--) {   // highest frequency first
            if (buckets[f] == null) continue;
            buckets[f].Sort();                                          // the tie rule: smaller value first
            foreach (int x in buckets[f]) {
                if (result.Count == k) break;
                result.Add(x);
            }
        }
        return result.ToArray();
    }
}
```

